template:
struct Meters⟦decl⟧

fn add(a: Meters, b: Meters) -> Meters {
    Meters(a.0 + b.0)
}

fn main() {
    let total = add(Meters(3), Meters(4));
    println!("{}", total.0);
}

tests:
#[test]
fn adds() {
    assert_eq!(add(Meters(3), Meters(4)).0, 7);
    assert_eq!(add(Meters(0), Meters(0)).0, 0);
}
